package com.gamelab.application;
import com.gamelab.domain.*; import com.gamelab.domain.economy.CoinWallet; import com.gamelab.pattern.observer.*; import com.gamelab.pattern.strategy.PlayerCombatStrategy; import java.util.Objects;
/** Coordinates both sides of combat and grants rewards exactly once when an enemy dies. */
public final class CombatService { private final GameEventBus events; private final RewardService rewards; private final CoinWallet wallet; public CombatService(GameEventBus events){this(events,null,null);} public CombatService(GameEventBus events,RewardService rewards,CoinWallet wallet){this.events=Objects.requireNonNull(events);if((rewards==null)!=(wallet==null))throw new IllegalArgumentException("Reward service and wallet must be provided together");this.rewards=rewards;this.wallet=wallet;}
 public int attack(PlayerCharacter player,Enemy enemy,PlayerCombatStrategy strategy){Objects.requireNonNull(player);Objects.requireNonNull(enemy);Objects.requireNonNull(strategy);if(!player.isAlive()||!enemy.isAlive())return 0;int damage=strategy.calculateDamage(player);if(damage<0)throw new IllegalStateException("Combat strategy returned negative damage");return applyEnemyDamage(enemy,damage,player);}
 public int damageEnemy(Enemy enemy,int damage){Objects.requireNonNull(enemy);if(damage<0)throw new IllegalArgumentException("Damage cannot be negative");return applyEnemyDamage(enemy,damage,null);}
 private int applyEnemyDamage(Enemy enemy,int damage,PlayerCharacter player){if(!enemy.isAlive())return 0;int before=enemy.getHealth();enemy.takeDamage(damage);int dealt=before-enemy.getHealth();events.publish(GameEventTypes.COMBAT_HIT,enemy.getName()+" took "+dealt+" damage");if(!enemy.isAlive()&&enemy.claimReward())grantReward(enemy,player);return dealt;}
 /** Enemy attacks Knight; PlayerCharacter owns defense mitigation. Returns actual health lost. */
 public int attackPlayer(Enemy enemy,PlayerCharacter player){Objects.requireNonNull(enemy);Objects.requireNonNull(player);if(!enemy.isAlive()||!player.isAlive())return 0;int before=player.getHealth();player.takeDamage(enemy.getDamage());int dealt=before-player.getHealth();events.publish(GameEventTypes.COMBAT_HIT,enemy.getName()+" hit "+player.getName()+" for "+dealt);return dealt;}
 private void grantReward(Enemy enemy,PlayerCharacter player){if(rewards!=null&&wallet!=null&&player!=null&&enemy.getRewardCoins()>0&&enemy.getRewardExperience()>0){if(enemy.isBoss())rewards.grantBossReward(enemy.getName(),enemy.getRewardCoins(),enemy.getRewardExperience(),wallet,player);else rewards.grantEnemyReward(enemy.getName(),enemy.getRewardCoins(),enemy.getRewardExperience(),wallet,player);}else if(enemy.isBoss())events.publish(GameEventTypes.BOSS_DEFEATED,enemy.getName()+" was defeated");else events.publish(GameEventTypes.ENEMY_KILLED,enemy.getName()+" was defeated");}
}
